boolean isDirectlyWithinFolder(Path folder, String rawPath) {
    try {
        Path path = Paths.get(rawPath);
        if (path.isAbsolute() || path.getParent() != null || path.getNameCount() != 1) {
            return false;
        }
        String name = path.toString();
        if (name.equals(".") || name.equals("..")) {
            return false;
        }
        Path resolved = folder.resolve(path).normalize();
        return resolved.getParent() != null && resolved.getParent().equals(folder.normalize());
